# -*- coding: utf-8 -*-
"""Technical indicator library - PRO edition.

Everything from the debugged edition plus MACD, Bollinger, CCI,
Williams %R, OBV, ROC momentum, pivot points and an EMA series helper
for charting. All functions are pure, defensive (short/empty series safe)
and deterministic.
"""
import math


# --------------------------------------------------------------------- EMA --
def calc_ema(closes, period):
    if not closes:
        return 0
    if len(closes) < period:
        k = 2 / (period + 1)
        ema = closes[0]
        for p in closes[1:]:
            ema = p * k + ema * (1 - k)
        return round(ema, 5)
    k = 2 / (period + 1)
    ema = sum(closes[:period]) / period
    for p in closes[period:]:
        ema = p * k + ema * (1 - k)
    return round(ema, 5)


def calc_ema_series(closes, period):
    """Full EMA series (for chart overlays)."""
    if not closes:
        return []
    k = 2 / (period + 1)
    out = [closes[0]]
    for p in closes[1:]:
        out.append(p * k + out[-1] * (1 - k))
    return [round(v, 5) for v in out]


# --------------------------------------------------------------------- RSI --
def calc_rsi(closes, period=14):
    if len(closes) < period + 1:
        return 50.0
    gains, losses = [], []
    for i in range(1, len(closes)):
        d = closes[i] - closes[i - 1]
        gains.append(max(d, 0))
        losses.append(max(-d, 0))
    ag = sum(gains[:period]) / period
    al = sum(losses[:period]) / period
    for i in range(period, len(gains)):
        ag = (ag * (period - 1) + gains[i]) / period
        al = (al * (period - 1) + losses[i]) / period
    if al == 0:
        return 100.0
    return round(100 - (100 / (1 + ag / al)), 2)


# --------------------------------------------------------------------- ATR --
def calc_atr(highs, lows, closes, period=14):
    n = min(len(highs), len(lows), len(closes))
    if n < period + 1:
        return 0
    trs = []
    for i in range(1, n):
        tr = max(highs[i] - lows[i],
                 abs(highs[i] - closes[i - 1]),
                 abs(lows[i] - closes[i - 1]))
        trs.append(tr)
    atr = sum(trs[:period]) / period
    for i in range(period, len(trs)):
        atr = (atr * (period - 1) + trs[i]) / period
    return round(atr, 5)


# --------------------------------------------------------------- Stoch RSI --
def calc_stoch_rsi(closes, rsi_period=14, stoch_period=14):
    if len(closes) < rsi_period + stoch_period + 1:
        return 50.0
    rsi_vals = []
    gains, losses = [], []
    for i in range(1, len(closes)):
        d = closes[i] - closes[i - 1]
        gains.append(max(d, 0))
        losses.append(max(-d, 0))
    ag = sum(gains[:rsi_period]) / rsi_period
    al = sum(losses[:rsi_period]) / rsi_period
    for i in range(rsi_period, len(gains)):
        ag = (ag * (rsi_period - 1) + gains[i]) / rsi_period
        al = (al * (rsi_period - 1) + losses[i]) / rsi_period
        rsi_vals.append(100.0 if al == 0 else 100 - (100 / (1 + ag / al)))
    if len(rsi_vals) < stoch_period:
        return 50.0
    hi = max(rsi_vals[-stoch_period:])
    lo = min(rsi_vals[-stoch_period:])
    if hi == lo:
        return 50.0
    return round(((rsi_vals[-1] - lo) / (hi - lo)) * 100, 2)


# -------------------------------------------------------------------- MACD --
def calc_macd(closes, fast=12, slow=26, signal=9):
    """Returns (macd, signal, histogram)."""
    if len(closes) < slow + signal:
        return 0.0, 0.0, 0.0
    ef = calc_ema_series(closes, fast)
    es = calc_ema_series(closes, slow)
    line = [f - s for f, s in zip(ef, es)]
    sig = calc_ema_series(line, signal)
    macd, sig_v = line[-1], sig[-1]
    return round(macd, 5), round(sig_v, 5), round(macd - sig_v, 5)


# -------------------------------------------------------------- Bollinger --
def calc_bollinger(closes, period=20, mult=2.0):
    """Returns (lower, mid, upper, %B)."""
    if len(closes) < period:
        return None, None, None, 0.5
    win = closes[-period:]
    mid = sum(win) / period
    var = sum((p - mid) ** 2 for p in win) / period
    sd = math.sqrt(var)
    up, lo = mid + mult * sd, mid - mult * sd
    pb = 0.5 if up == lo else (closes[-1] - lo) / (up - lo)
    return round(lo, 5), round(mid, 5), round(up, 5), round(max(0.0, min(1.0, pb)), 3)


# --------------------------------------------------------------------- CCI --
def calc_cci(highs, lows, closes, period=20):
    n = min(len(highs), len(lows), len(closes))
    if n < period:
        return 0.0
    tp = [(highs[i] + lows[i] + closes[i]) / 3 for i in range(n)]
    win = tp[-period:]
    mean = sum(win) / period
    md = sum(abs(v - mean) for v in win) / period
    if md == 0:
        return 0.0
    return round((tp[-1] - mean) / (0.015 * md), 2)


# ------------------------------------------------------------- Williams %R --
def calc_williams_r(highs, lows, closes, period=14):
    n = min(len(highs), len(lows), len(closes))
    if n < period:
        return -50.0
    hh = max(highs[-period:])
    ll = min(lows[-period:])
    if hh == ll:
        return -50.0
    return round(((hh - closes[-1]) / (hh - ll)) * -100, 2)


# --------------------------------------------------------------------- OBV --
def calc_obv(closes, volumes):
    n = min(len(closes), len(volumes))
    if n < 2:
        return 0.0
    obv = 0.0
    for i in range(1, n):
        if closes[i] > closes[i - 1]:
            obv += volumes[i]
        elif closes[i] < closes[i - 1]:
            obv -= volumes[i]
    return round(obv, 1)


# ---------------------------------------------------------------- ROC (mom) --
def calc_momentum(closes, period=10):
    """Rate of change in percent."""
    if len(closes) <= period or closes[-1 - period] == 0:
        return 0.0
    return round((closes[-1] / closes[-1 - period] - 1) * 100, 3)


# ------------------------------------------------------------------ Pivots --
def calc_pivots(high, low, close):
    """Classic floor pivots from the previous bar."""
    p = (high + low + close) / 3
    return {
        "p": round(p, 2),
        "r1": round(2 * p - low, 2),
        "s1": round(2 * p - high, 2),
        "r2": round(p + (high - low), 2),
        "s2": round(p - (high - low), 2),
    }


# ------------------------------------------------------------------ Volume --
def calc_volume_analysis(volumes):
    if len(volumes) < 20:
        return "normal"
    avg = sum(volumes[-20:]) / 20
    if avg <= 0:
        return "normal"
    cur = volumes[-1]
    if cur > avg * 2:
        return "very_high"
    if cur > avg * 1.5:
        return "high"
    if cur < avg * 0.5:
        return "very_low"
    if cur < avg * 0.7:
        return "low"
    return "normal"


# -------------------------------------------------------- Candle patterns --
def calc_candle_pattern(opens, highs, lows, closes):
    if len(closes) < 3:
        return "unknown", 0
    body = closes[-1] - opens[-1]
    upper = highs[-1] - max(opens[-1], closes[-1])
    lower = min(opens[-1], closes[-1]) - lows[-1]
    total = highs[-1] - lows[-1]
    if total == 0:
        return "doji", 0
    ratio = abs(body) / total
    if ratio < 0.1:
        return "doji", 0
    if upper > abs(body) * 2 and lower < abs(body) * 0.5:
        return "shooting_star", -1
    if lower > abs(body) * 2 and upper < abs(body) * 0.5:
        return "hammer", 1
    if body > 0 and ratio > 0.7:
        return "strong_bull", 1
    if body < 0 and ratio > 0.7:
        return "strong_bear", -1
    if body > 0:
        return "bull", 0.5
    return "bear", -0.5


def calc_all(closes, highs, lows, opens, volumes=None):
    """One-shot feature vector used by strategies & the dashboard."""
    vols = volumes or [0.0] * len(closes)
    bb_lo, bb_mid, bb_up, bb_pb = calc_bollinger(closes)
    macd, sig, hist = calc_macd(closes)
    return {
        "ema9": calc_ema(closes, 9),
        "ema21": calc_ema(closes, 21),
        "rsi": calc_rsi(closes),
        "atr": calc_atr(highs, lows, closes),
        "stoch_k": calc_stoch_rsi(closes),
        "macd": macd, "macd_sig": sig, "macd_hist": hist,
        "bb_lo": bb_lo, "bb_mid": bb_mid, "bb_up": bb_up, "bb_pb": bb_pb,
        "cci": calc_cci(highs, lows, closes),
        "wr": calc_williams_r(highs, lows, closes),
        "obv": calc_obv(closes, vols),
        "mom": calc_momentum(closes),
        "pivots": calc_pivots(highs[-2], lows[-2], closes[-2]) if len(closes) >= 2 and len(highs) >= 2 and len(lows) >= 2 else {},
        "volume": calc_volume_analysis(vols),
        "pattern": calc_candle_pattern(opens, highs, lows, closes),
    }

# -*- coding: utf-8 -*-
"""Optional outbound alerts - PRO edition.

Fire-and-forget notifications on OPEN / CLOSE / BLOCK events.
Supports a generic JSON webhook and/or Telegram. Disabled silently when
not configured. Rate-limited to avoid spam. Uses only the stdlib so the
installer stays light.
"""
import json
import threading
import time
import urllib.request

_MIN_INTERVAL = 2.0


class Notifier:
    def __init__(self, cfg):
        self.cfg = cfg
        self._last = 0.0
        self.sent = 0
        self.errors = 0

    @property
    def enabled(self):
        return bool(self.cfg.notify_url or (self.cfg.tg_token and self.cfg.tg_chat))

    def notify(self, event, text):
        if not self.enabled:
            return False
        now = time.time()
        if now - self._last < _MIN_INTERVAL:
            return False
        self._last = now
        payload = {"event": event, "text": text, "ts": now}

        def _send():
            try:
                if self.cfg.notify_url:
                    req = urllib.request.Request(
                        self.cfg.notify_url,
                        data=json.dumps(payload).encode(),
                        headers={"Content-Type": "application/json"})
                    urllib.request.urlopen(req, timeout=5)
                if self.cfg.tg_token and self.cfg.tg_chat:
                    url = f"https://api.telegram.org/bot{self.cfg.tg_token}/sendMessage"
                    body = json.dumps({"chat_id": self.cfg.tg_chat,
                                       "text": f"[FlyGold] {event}: {text}"}).encode()
                    urllib.request.urlopen(urllib.request.Request(
                        url, data=body,
                        headers={"Content-Type": "application/json"}), timeout=5)
                self.sent += 1
            except Exception:
                self.errors += 1

        threading.Thread(target=_send, daemon=True).start()
        return True

    def test(self):
        if not self.enabled:
            return {"ok": False, "error": "notifications not configured "
                                          "(set NOTIFY_URL or TELEGRAM_*)"}
        ok = self.notify("TEST", "Fly-Gold-Pro notifier self-test")
        return {"ok": ok, "sent_total": self.sent, "errors": self.errors}

    def stats(self):
        return {"enabled": self.enabled, "sent": self.sent,
                "errors": self.errors}

# -*- coding: utf-8 -*-
"""Account-level risk manager - PRO edition.

Guards that sit BETWEEN the signal and the order:
  * daily loss cap (resets at UTC midnight)
  * max drawdown from equity peak
  * consecutive-loss cooldown
  * session-hours filter
  * spread filter
  * max simultaneous positions (enforced server-side as well)

Every decision is recorded so the dashboard can explain WHY a trade was
skipped.
"""
import threading
import time
from datetime import datetime, timezone


class RiskManager:
    def __init__(self, cfg):
        self.cfg = cfg
        self._lock = threading.Lock()
        self.day = datetime.now(timezone.utc).date()
        self.daily_pnl = 0.0
        self.peak_equity = None
        self.max_dd_pct = 0.0
        self.consec_losses = 0
        self.cooldown_until = 0.0
        self.blocks = {}          # reason -> count (for the dashboard)
        self.last_reason = None

    # ------------------------------------------------------------ lifecycle
    def register_close(self, pnl, equity=None):
        with self._lock:
            today = datetime.now(timezone.utc).date()
            if today != self.day:
                self.day = today
                self.daily_pnl = 0.0
            self.daily_pnl = round(self.daily_pnl + pnl, 2)
            if pnl < 0:
                self.consec_losses += 1
                if self.consec_losses >= self.cfg.cooldown_losses:
                    self.cooldown_until = time.time() + self.cfg.cooldown_sec
            else:
                self.consec_losses = 0
            if equity is not None:
                self._update_dd(equity)

    def _update_dd(self, equity):
        if self.peak_equity is None or equity > self.peak_equity:
            self.peak_equity = equity
        if self.peak_equity:
            dd = max(0.0, (self.peak_equity - equity) / self.peak_equity * 100)
            self.max_dd_pct = round(max(self.max_dd_pct, dd), 2)

    # -------------------------------------------------------------- gating
    def can_trade(self, balance=0.0, equity=None, spread=None):
        """Return (ok, reason)."""
        with self._lock:
            today = datetime.now(timezone.utc).date()
            if today != self.day:
                self.day = today
                self.daily_pnl = 0.0
            if equity is not None:
                self._update_dd(equity)

            hour = datetime.now(timezone.utc).hour
            if not (self.cfg.session_start <= hour < self.cfg.session_end):
                return self._block("session_hours")
            if self.daily_pnl <= -self.cfg.max_daily_loss_usd:
                return self._block("daily_loss_cap")
            if self.max_dd_pct >= self.cfg.max_drawdown_pct:
                return self._block("max_drawdown")
            if time.time() < self.cooldown_until:
                return self._block("cooldown")
            if self.cfg.spread_max > 0 and spread is not None \
                    and spread > self.cfg.spread_max:
                return self._block("spread")
            if self.cfg.sl_usd > balance * self.cfg.risk_pct / 100.0 > 0:
                return self._block("risk_budget")
            self.last_reason = None
            return True, "ok"

    def _block(self, reason):
        self.blocks[reason] = self.blocks.get(reason, 0) + 1
        self.last_reason = reason
        return False, reason

    # -------------------------------------------------------------- stats
    def stats(self):
        with self._lock:
            return {
                "day": str(self.day),
                "daily_pnl": self.daily_pnl,
                "daily_loss_cap": self.cfg.max_daily_loss_usd,
                "peak_equity": self.peak_equity,
                "max_drawdown_pct": self.max_dd_pct,
                "drawdown_cap_pct": self.cfg.max_drawdown_pct,
                "consec_losses": self.consec_losses,
                "cooldown_sec_left": max(0.0, round(self.cooldown_until - time.time(), 1)),
                "blocks": dict(self.blocks),
                "last_reason": self.last_reason,
            }

# -*- coding: utf-8 -*-
"""Gold Fly+Jev HFT Trader - PRO Server.

Fly brain + strategy ensemble + TypeSafe Jev + MT5 / paper simulator,
guarded by an account-level risk manager, persisted in a SQLite journal,
optionally pushed out as alerts, and fully observable from the
multi-tab dashboard. All 9 original critical bugs remain fixed.

NEW (PRO): strategy engine (7 strategies + ensemble), risk manager,
journal, notifications, backtest & sweep APIs, config API, CLI sibling.
"""
import sys
import io
import os
import traceback

_REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if _REPO_ROOT not in sys.path:
    sys.path.insert(0, _REPO_ROOT)

if hasattr(sys.stdout, "buffer"):
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8",
                                  line_buffering=True)
if hasattr(sys.stderr, "buffer"):
    sys.stderr = io.TextIOWrapper(sys.stderr.buffer, encoding="utf-8",
                                  line_buffering=True)

import threading
import time
from datetime import datetime

from flask import Flask, render_template, jsonify, request
from flask_socketio import SocketIO

from src.config import CFG
from src.fly_brain import FlyBrain
from src import indicators as ind
from src import mt5_trader as mt5
from src.strategies import StrategyEngine, REGISTRY
from src.risk_manager import RiskManager
from src.journal import Journal
from src.notifications import Notifier
from src import backtest
from src import playbook

app = Flask(
    __name__,
    template_folder=os.path.join(_REPO_ROOT, "templates"),
    static_folder=os.path.join(_REPO_ROOT, "static"),
)
app.config["SECRET_KEY"] = CFG.secret_key
socketio = SocketIO(app, cors_allowed_origins="*", async_mode="threading")

try:
    from typesafe_sdk import TypeSafeClient, Choice, Score  # type: ignore
    client = TypeSafeClient()
    JEV_AVAILABLE = True
except Exception:
    JEV_AVAILABLE = False
    print("[WARN] TypeSafe SDK not available - ensemble strategies drive signals")

TIMEFRAMES = ["M1", "M5", "M15", "M30", "H1", "H4", "D1"]

trading_state = {
    "running": False, "cycle": 0, "last_analysis": None,
    "price_history": [], "actions_log": [], "error": None,
    "indicators": {}, "mode": "paper", "feats": {}, "latencies": [],
    "fly_brain": {"status": "loading"},
}

_state_lock = threading.Lock()
_loop_thread = None
_trail_peaks = {}
_open_meta = {}

fly_brain = None
engine = StrategyEngine(CFG.strategy)
risk = RiskManager(CFG)
journal = Journal()
notifier = Notifier(CFG)


def init_fly():
    global fly_brain
    fly_brain = FlyBrain()
    trading_state["fly_brain"]["status"] = fly_brain.status


def current_mode():
    return "paper" if mt5.use_paper() else "live"


# ------------------------------------------------------------------ data ---
def get_multi_tf_data():
    data, feats = {}, {}
    for name in TIMEFRAMES:
        rates = mt5.get_rates(mt5.GOLD, name, 60)
        if rates is None or len(rates["closes"]) < 21:
            continue
        c, h, l, o, v = (rates["closes"], rates["highs"], rates["lows"],
                         rates["opens"], rates["volumes"])
        f = ind.calc_all(c, h, l, o, v)
        feats[name] = f
        data[name] = {
            "close": round(c[-1], 2), "open": round(o[-1], 2),
            "high": round(h[-1], 2), "low": round(l[-1], 2),
            "ema21": f["ema21"], "ema9": f["ema9"], "rsi": f["rsi"],
            "atr": f["atr"], "stoch_k": f["stoch_k"],
            "ema_trend": "bull" if c[-1] > f["ema21"] else "bear",
            "rsi_zone": ("overbought" if f["rsi"] > 70
                         else "oversold" if f["rsi"] < 30 else "neutral"),
            "closes": c[-20:], "highs": h[-20:],
            "lows": l[-20:], "opens": o[-20:],
        }
    return data, feats


def fly_analyze(tf_data):
    if fly_brain is None:
        return {"score": 0, "label": "no_brain", "confidence": 0,
                "pam11": 0, "ppl101": 0, "kc": 0, "spikes": 0, "status": "off"}
    m1 = tf_data.get("M1", {})
    if not m1:
        return {"score": 0, "label": "no_data", "confidence": 0,
                "pam11": 0, "ppl101": 0, "kc": 0, "spikes": 0,
                "status": fly_brain.status}
    return fly_brain.analyze(m1["closes"], m1["highs"], m1["lows"], m1["opens"])


def analyze(tf_data, feats, fly_signal, pos_count):
    """Jev if available, otherwise the strategy ensemble."""
    if JEV_AVAILABLE:
        try:
            state = {"asset": "XAUUSD",
                     "current_price": tf_data.get("M1", {}).get("close", 0),
                     "fly_brain": fly_signal, "positions_count": pos_count}
            resp = client.system_one(
                state=state,
                questions={
                    "trade_signal": Choice(
                        instructions="Combine fly brain score, EMA21, RSI, ATR.",
                        criteria={"strong_buy": "Fly>0.5 & EMA bull & RSI<70",
                                  "buy": "Fly>0.2 or EMA bull",
                                  "hold": "Mixed",
                                  "sell": "Fly<-0.2 or EMA bear",
                                  "strong_sell": "Fly<-0.5 & EMA bear & RSI>30"}),
                    "position_action": Choice(
                        instructions="Position management?",
                        criteria={"hold_all": "Keep", "close_all": "Close all",
                                  "add_buy": "Add buys", "add_sell": "Add sells",
                                  "reverse": "Reverse"}),
                    "confidence": Score(instructions="Confidence?",
                                        criteria=["Very low", "Low", "Medium",
                                                  "High", "Very high"])}).answers
            return {"signal": resp["trade_signal"].choice,
                    "conf": round(resp["confidence"].score, 2),
                    "pos_action": resp["position_action"].choice,
                    "votes": {}, "source": "jev"}
        except Exception as e:
            print(f"[WARN] Jev call failed: {e}")

    m1 = {**feats.get("M1", {}), **tf_data.get("M1", {})}
    tfs = {name: {**feats.get(name, {}), **tf_data.get(name, {})}
           for name in tf_data}
    ctx = {"m1": m1, "tfs": tfs, "fly": fly_signal}
    res = engine.evaluate(ctx)
    return {"signal": res["signal"], "conf": res["conf"],
            "pos_action": "hold_all", "votes": res["votes"],
            "score": res["score"], "source": CFG.strategy}


# ------------------------------------------------------------------ risk ---
def manage_positions():
    """TP / SL / trailing + journal + alerts on every close."""
    closed = []
    positions = mt5.get_raw_positions(mt5.GOLD)
    alive = set()
    for pos in positions:
        pnl = round(pos.profit, 2)
        alive.add(pos.ticket)
        peak = max(_trail_peaks.get(pos.ticket, pnl), pnl)
        _trail_peaks[pos.ticket] = peak
        reason = None
        if pnl >= CFG.tp_usd:
            reason = "TP"
        elif pnl <= -CFG.sl_usd:
            reason = "SL"
        elif CFG.trail_usd > 0 and peak >= CFG.trail_usd \
                and pnl <= peak - CFG.trail_usd:
            reason = "TRAIL"
        if reason and mt5.close_position(pos):
            meta = _open_meta.pop(pos.ticket, {})
            acct = mt5.get_account()
            risk.register_close(pnl, equity=acct["equity"] if acct else None)
            side = "BUY" if pos.type == 0 else "SELL"
            sign = 1.0 if pos.type == 0 else -1.0
            close_px = round(pos.price_open + sign * pnl /
                             max(pos.volume * 100.0, 1e-9), 2)
            journal.record(mt5.GOLD, side, pos.volume, pos.price_open,
                           close_px, pnl, reason,
                           meta.get("strategy", "?"), current_mode())
            notifier.notify("CLOSE", f"{reason} {side} PnL {pnl:+.2f}")
            closed.append({"ticket": pos.ticket, "reason": reason,
                           "side": side, "pnl": pnl})
    for t in [t for t in _trail_peaks if t not in alive]:
        _trail_peaks.pop(t, None)
    return closed


def open_with_meta(side, strategy_label):
    acct = mt5.get_account()
    balance = acct["balance"] if acct else 10000.0
    vol, _ = CFG.size_volume(balance)
    before = {p.ticket for p in mt5.get_raw_positions(mt5.GOLD)}
    ok, price = mt5.open_position(side, vol)
    if ok:
        for p in mt5.get_raw_positions(mt5.GOLD):
            if p.ticket not in before:
                _open_meta[p.ticket] = {"strategy": strategy_label,
                                        "ts": time.time()}
        notifier.notify("OPEN", f"{side} {vol} @ {price}")
    return ok, price


# ------------------------------------------------------------------ loop ---
def trading_loop():
    try:
        ok, msg = mt5.connect()
        if not ok:
            trading_state["error"] = f"connect failed: {msg}"
            print(f"[LOOP] connect failed: {msg}")
            return
        trading_state["running"] = True
        trading_state["error"] = None
        print(f"[LOOP] Started | {msg} | mode={current_mode()} "
              f"| strategy={CFG.strategy}")

        while trading_state["running"]:
            try:
                trading_state["cycle"] += 1
                c = trading_state["cycle"]
                now = datetime.now().strftime("%H:%M:%S")

                tf_data, feats = get_multi_tf_data()
                m1f = feats.get("M1", {})
                indicators = {f"{tf}_{k}": v for tf, f in feats.items()
                              for k, v in f.items()
                              if k in ("ema21", "rsi", "atr", "stoch_k",
                                       "macd_hist", "bb_pb", "cci", "wr")}
                trading_state["indicators"] = indicators

                fly_signal = fly_analyze(tf_data)
                trading_state["fly_brain"].update(fly_signal)

                positions_raw = mt5.get_raw_positions(mt5.GOLD)
                pos_count = len(positions_raw)
                t0 = time.perf_counter()
                analysis = analyze(tf_data, feats, fly_signal, pos_count)
                ms = (time.perf_counter() - t0) * 1000.0
                trading_state["latencies"].append(round(ms, 1))
                trading_state["latencies"] = trading_state["latencies"][-100:]
                signal, conf = analysis["signal"], analysis["conf"]

                prism = playbook.gate({"feats": feats, "fly": fly_signal})
                prism_ok = prism.get("gate", 1.0) >= 0.6

                exec_results = []

                if analysis["pos_action"] == "close_all" and positions_raw:
                    for pos in positions_raw:
                        if mt5.close_position(pos):
                            pnl = round(pos.profit, 2)
                            risk.register_close(pnl)
                            journal.record(mt5.GOLD,
                                           "BUY" if pos.type == 0 else "SELL",
                                           pos.volume, pos.price_open,
                                           pos.price_open, pnl, "SIGNAL",
                                           CFG.strategy, current_mode())
                            exec_results.append(f"CLOSED PnL:{pnl:+.2f}")

                for cl in manage_positions():
                    exec_results.append(f"{cl['reason']}-CLOSED {cl['side']} "
                                        f"PnL:{cl['pnl']:+.2f}")

                pos_count = len(mt5.get_raw_positions(mt5.GOLD))
                tick = mt5.get_tick(mt5.GOLD)
                spread = tick["spread"] if tick else None
                acct = mt5.get_account() or {}

                gate_ok, gate_reason = risk.can_trade(
                    balance=acct.get("balance", 0),
                    equity=acct.get("equity"), spread=spread)

                if gate_ok and prism_ok and pos_count < CFG.max_positions:
                    if signal == "strong_buy" and conf >= 3:
                        ok_o, d = open_with_meta("BUY", CFG.strategy)
                        if ok_o:
                            exec_results.append(f"BUY @ {d}")
                    elif signal == "strong_sell" and conf >= 3:
                        ok_o, d = open_with_meta("SELL", CFG.strategy)
                        if ok_o:
                            exec_results.append(f"SELL @ {d}")
                    elif signal == "buy" and conf >= 2 \
                            and fly_signal["score"] > 0.3:
                        ok_o, d = open_with_meta("BUY", CFG.strategy)
                        if ok_o:
                            exec_results.append(f"BUY @ {d}")
                    elif signal == "sell" and conf >= 2 \
                            and fly_signal["score"] < -0.3:
                        ok_o, d = open_with_meta("SELL", CFG.strategy)
                        if ok_o:
                            exec_results.append(f"SELL @ {d}")

                pos_list = mt5.get_positions()
                detail = " | ".join(exec_results) if exec_results else "HOLD"
                price = tf_data.get("M1", {}).get("close", 0)

                log = {"time": now, "cycle": c, "price": price,
                       "trend": fly_signal["label"], "action": signal,
                       "risk": conf, "executed": bool(exec_results),
                       "detail": detail}
                trading_state["actions_log"].append(log)
                trading_state["actions_log"] = \
                    trading_state["actions_log"][-100:]
                trading_state["price_history"].append(
                    {"time": now, "price": price})
                trading_state["price_history"] = \
                    trading_state["price_history"][-200:]

                usd_tick = mt5.get_tick(mt5.USDCAD)
                eur_tick = mt5.get_tick(mt5.EURUSD)

                update = {
                    "time": now, "cycle": c, "price": price,
                    "usdcad": usd_tick["bid"] if usd_tick else 0,
                    "eurusd": eur_tick["bid"] if eur_tick else 0,
                    "trend": fly_signal["label"],
                    "trend_conf": fly_signal["confidence"],
                    "action": signal, "action_conf": conf,
                    "risk": conf, "votes": analysis.get("votes", {}),
                    "signal_source": analysis.get("source", "?"),
                    "mode": current_mode(), "error": None,
                    "gate": gate_reason,
                    "result": {"executed": bool(exec_results),
                               "detail": detail},
                    "positions": pos_list,
                    "balance": acct.get("balance", 0),
                    "equity": acct.get("equity", 0),
                    "profit": acct.get("profit", 0),
                    "indicators": indicators,
                    "fly_brain": fly_signal,
                    # live candles for the 3D Fly Brain Room (25-module UI)
                    "m1": {"closes": tf_data.get("M1", {}).get("closes"),
                           "highs": tf_data.get("M1", {}).get("highs"),
                           "lows": tf_data.get("M1", {}).get("lows"),
                           "opens": tf_data.get("M1", {}).get("opens")},
                    "analysis": {"signal": signal,
                                 "pos_action": analysis["pos_action"],
                                 "confidence": conf},
                }
                trading_state["last_analysis"] = update
                socketio.emit("update", update)

                print(f"[{c}] {now} P={price} Fly={fly_signal['label']}"
                      f"({fly_signal['score']:.3f}) Sig={signal}"
                      f"[{analysis.get('source')}] gate={gate_reason} "
                      f"Pos={pos_count} | {detail}")
                time.sleep(CFG.loop_delay)

            except Exception as e:
                trading_state["error"] = f"{type(e).__name__}: {e}"
                print(f"[ERROR] {e}\n{traceback.format_exc()}")
                time.sleep(CFG.loop_delay)
    except Exception as e:
        trading_state["error"] = f"FATAL: {e}"
        print(f"[FATAL] {e}\n{traceback.format_exc()}")
    finally:
        mt5.disconnect()
        trading_state["running"] = False
        print("[LOOP] Stopped")


