# -*- coding: utf-8 -*-
"""Strategy engine - PRO edition.

Seven independent strategies vote with a strength in [0, 1] and a
direction in {-1, 0, +1}. The ensemble combines them with per-strategy
weights into a single score in [-1, 1] which the server maps onto the
legacy signal vocabulary (strong_buy/buy/hold/sell/strong_sell) so the
execution gates stay unchanged.

Context (`ctx`) layout produced by the server / backtester:
    ctx = {
      "m1": {"closes","highs","lows","opens","volumes", feats...},
      "tfs": {name: feats...},
      "fly": {"score","label","confidence",...},
    }
"""


class Strategy:
    name = "base"
    weight = 1.0

    def evaluate(self, ctx):
        """Return (vote in {-1,0,1}, strength in [0,1])."""
        raise NotImplementedError


def _clamp(v):
    return max(0.0, min(1.0, v))


class FlyMomentum(Strategy):
    """The original idea: dopaminergic fly-brain score."""
    name, weight = "fly_momentum", 1.4

    def evaluate(self, ctx):
        s = (ctx.get("fly") or {}).get("score", 0)
        if abs(s) < 0.05:
            return 0, 0.0
        return (1 if s > 0 else -1), _clamp(abs(s) * 1.6)


class EmaCross(Strategy):
    """EMA9 vs EMA21 trend with price confirmation."""
    name, weight = "ema_cross", 1.0

    def evaluate(self, ctx):
        f = ctx["m1"]
        if f["ema9"] > f["ema21"] and f["closes"][-1] > f["ema21"]:
            return 1, _clamp(abs(f["ema9"] - f["ema21"]) / max(f["atr"], 1e-9))
        if f["ema9"] < f["ema21"] and f["closes"][-1] < f["ema21"]:
            return -1, _clamp(abs(f["ema9"] - f["ema21"]) / max(f["atr"], 1e-9))
        return 0, 0.0


class RsiReversal(Strategy):
    """Fade the extremes."""
    name, weight = "rsi_reversal", 0.8

    def evaluate(self, ctx):
        r = ctx["m1"]["rsi"]
        if r < 28:
            return 1, _clamp((30 - r) / 25)
        if r > 72:
            return -1, _clamp((r - 70) / 25)
        return 0, 0.0


class BollingerFade(Strategy):
    """Mean reversion off the bands."""
    name, weight = "bollinger_fade", 0.8

    def evaluate(self, ctx):
        pb = ctx["m1"]["bb_pb"]
        if pb <= 0.05:
            return 1, _clamp(0.4 + (0.05 - pb) * 4)
        if pb >= 0.95:
            return -1, _clamp(0.4 + (pb - 0.95) * 4)
        return 0, 0.0


class MacdMomentum(Strategy):
    """Histogram direction + sign."""
    name, weight = "macd_momentum", 1.0

    def evaluate(self, ctx):
        f = ctx["m1"]
        h = f["macd_hist"]
        atr = max(f["atr"], 1e-9)
        if abs(h) < atr * 0.02:
            return 0, 0.0
        return (1 if h > 0 else -1), _clamp(abs(h) / (atr * 0.35))


class CandlePatternStrategy(Strategy):
    """Classic single-candle edges (hammer / shooting star / marubozu)."""
    name, weight = "candle_pattern", 0.9

    def evaluate(self, ctx):
        _, bias = ctx["m1"]["pattern"]
        if bias == 0:
            return 0, 0.0
        return (1 if bias > 0 else -1), _clamp(abs(bias))


class MultiTFTrend(Strategy):
    """Higher-timeframe trend alignment (M15/H1/H4 EMA21)."""
    name, weight = "multi_tf_trend", 1.2

    def evaluate(self, ctx):
        votes = []
        for tf in ("M15", "H1", "H4"):
            info = (ctx.get("tfs") or {}).get(tf)
            if not info:
                continue
            bull = info.get("close", 0) > info.get("ema21", 0)
            votes.append(1 if bull else -1)
        if not votes:
            return 0, 0.0
        avg = sum(votes) / len(votes)
        if abs(avg) < 0.34:
            return 0, 0.0
        return (1 if avg > 0 else -1), _clamp(abs(avg))


REGISTRY = {s.name: s for s in (
    FlyMomentum(), EmaCross(), RsiReversal(), BollingerFade(),
    MacdMomentum(), CandlePatternStrategy(), MultiTFTrend(),
)}


class StrategyEngine:
    """Runs one named strategy or the weighted ensemble."""

    def __init__(self, mode="ensemble"):
        self.mode = mode if mode in REGISTRY else "ensemble"

    def evaluate(self, ctx):
        """-> dict(signal, score, conf, votes)"""
        if self.mode != "ensemble":
            st = REGISTRY[self.mode]
            vote, strength = st.evaluate(ctx)
            score = vote * strength
            return self._shape(score, {st.name: (vote, strength)})

        num = 0.0
        den = 0.0
        votes = {}
        for st in REGISTRY.values():
            vote, strength = st.evaluate(ctx)
            votes[st.name] = (vote, round(strength, 2))
            num += st.weight * vote * strength
            den += st.weight
        score = num / den if den else 0.0
        return self._shape(score, votes)

    @staticmethod
    def _shape(score, votes):
        score = max(-1.0, min(1.0, score))
        if score >= 0.55:
            signal = "strong_buy"
        elif score >= 0.22:
            signal = "buy"
        elif score <= -0.55:
            signal = "strong_sell"
        elif score <= -0.22:
            signal = "sell"
        else:
            signal = "hold"
        conf = min(5, round(abs(score) * 6))
        return {"signal": signal, "score": round(score, 3),
                "conf": conf, "votes": votes}

# -*- coding: utf-8 -*-
"""Jev Playbook — 20 adapted patterns from the community checklist.

Each pNN_*.py module exposes META + run(ctx) and is auto-registered.
All modules are deterministic and work WITHOUT the TypeSafe SDK (local
judges mimic Choice/Score); when the SDK exists they may enrich output.
"""
import importlib
import pkgutil

MODULES = []
for _m in sorted(pkgutil.iter_modules(__path__), key=lambda m: m.name):
    if _m.name.startswith("p") and _m.name[1:3].isdigit():
        MODULES.append(importlib.import_module(f"src.playbook.{_m.name}"))

BY_ID = {m.META["id"]: m for m in MODULES}


def run_all(ctx):
    out = {}
    for m in MODULES:
        try:
            out[m.META["id"]] = {**m.META, "result": m.run(ctx)}
        except Exception as e:  # a playbook module must never kill the app
            out[m.META["id"]] = {**m.META,
                                 "result": {"verdict": "error", "detail": str(e)}}
    return out


def gate(ctx):
    """P16 Prism as a live entry gate (used by the trading loop)."""
    try:
        return BY_ID["P16"].run(ctx)
    except Exception:
        return {"gate": 1.0, "verdict": "neutral"}

# -*- coding: utf-8 -*-
"""P01 — jev-ultrafast: latency-tiered decision path.
Jev judges the speed tier; heavy compute only when the loop is fast."""
META = {"id": "P01", "name": "ultrafast", "inspired_by": "jev-ultrafast",
        "desc": "Pick the decision path by measured latency (full ensemble "
                "only on the fast tier)."}


def run(ctx):
    ms = ctx.get("latency_ms", 999)
    if ms < 100:
        tier, path = "ultrafast", "full ensemble + fly brain"
    elif ms < 400:
        tier, path = "balanced", "top-3 strategies only"
    else:
        tier, path = "minimal", "fly score only"
    return {"latency_ms": round(ms, 1), "tier": tier, "path": path,
            "verdict": tier}

# -*- coding: utf-8 -*-
"""P02 — fast-jev-compaction: prune useless state, keep originals."""
META = {"id": "P02", "name": "compaction", "inspired_by":
        "fast-jev-compaction",
        "desc": "Drop near-zero-information indicators before the Jev call."}


def run(ctx):
    f = (ctx.get("feats") or {}).get("M1", {})
    scale = {"rsi": 50.0, "stoch_k": 50.0, "cci": 100.0, "wr": 50.0,
             "bb_pb": 0.5, "macd_hist": 0.3, "mom": 0.3}
    kept, dropped = [], []
    for k, norm in scale.items():
        val = f.get(k)
        if val is None:
            dropped.append(k)
            continue
        info = abs(val - (0 if k in ("macd_hist", "mom") else norm)) \
            / max(abs(norm), 1e-9)
        (kept if info > 0.12 else dropped).append(k)
    total = len(kept) + len(dropped) or 1
    return {"kept": kept, "dropped": dropped,
            "ratio": round(len(kept) / total, 2),
            "verdict": f"keep {len(kept)}/{total}"}

# -*- coding: utf-8 -*-
"""P03 — json-render: generative UI spec (Jev picks components, not pixels)."""
META = {"id": "P03", "name": "json_render", "inspired_by": "json-render",
        "desc": "Emit a widget spec for the dashboard instead of raw HTML."}


def run(ctx):
    f = (ctx.get("feats") or {}).get("M1", {})
    widgets = [{"type": "price_card", "props": {"symbol": "XAUUSD"}}]
    if (f.get("atr") or 0) > 0:
        widgets.append({"type": "volatility_banner",
                        "props": {"atr": f["atr"],
                                  "level": "high" if f["atr"] > 1 else "normal"}})
    if ctx.get("positions"):
        widgets.append({"type": "positions_table",
                        "props": {"rows": len(ctx["positions"])}})
    if abs((f.get("rsi") or 50) - 50) > 20:
        widgets.append({"type": "rsi_gauge", "props": {"value": f["rsi"]}})
    widgets.append({"type": "fly_room_3d", "props": {"quality": "auto"}})
    return {"widgets": widgets, "count": len(widgets),
            "verdict": f"{len(widgets)} widgets"}

