# -*- coding: utf-8 -*-
"""P06 — SemDecide: classify / score / filter from the shell."""
META = {"id": "P06", "name": "semdecide", "inspired_by": "SemDecide",
        "desc": "CLI-grade semantic decisions for pipelines & hooks."}


def classify(text):
    t = text.lower()
    if any(w in t for w in ("overbought", "bear", "sell", "down")):
        return "bearish"
    if any(w in t for w in ("oversold", "bull", "buy", "up")):
        return "bullish"
    return "neutral"


def score(text):
    return round(min(1.0, len(text.split()) / 12.0), 2)


def filter_items(items, min_score=0.3):
    return [i for i in items if score(str(i)) >= min_score]


def run(ctx):
    f = (ctx.get("feats") or {}).get("M1", {})
    txt = f"rsi {f.get('rsi')} mom {f.get('mom')} " + \
        ("bull" if f.get("ema_trend") == "bull" else "bear")
    return {"classify": classify(txt), "score": score(txt),
            "filter_example": len(filter_items(["short", "a much longer and "
                                                "informative market note"])),
            "verdict": classify(txt)}

# -*- coding: utf-8 -*-
"""P07 — jev-codex-router: judge difficulty, then pick the strategy tier."""
META = {"id": "P07", "name": "router", "inspired_by": "jev-codex-router",
        "desc": "Market difficulty -> strategy subset + reasoning depth."}


def run(ctx):
    f = (ctx.get("feats") or {}).get("M1", {})
    difficulty = min(1.0, (f.get("atr") or 0) / 1.5 * 0.5 +
                     abs((f.get("rsi") or 50) - 50) / 50 * 0.5)
    if difficulty < 0.33:
        tier, strat = "fast", ["fly_momentum", "ema_cross"]
    elif difficulty < 0.66:
        tier, strat = "balanced", ["ensemble"]
    else:
        tier, strat = "deep", ["multi_tf_trend", "rsi_reversal",
                               "bollinger_fade"]
    return {"difficulty": round(difficulty, 2), "tier": tier,
            "strategies": strat, "verdict": tier}

# -*- coding: utf-8 -*-
