# -*- coding: utf-8 -*-
"""P11 — agent-desktop style: read the account tree, pick the next action."""
META = {"id": "P11", "name": "autopilot", "inspired_by": "agent-desktop",
        "desc": "Structured account tree -> next best click (action)."}


def run(ctx):
    pos = ctx.get("positions") or []
    acct = ctx.get("account") or {}
    if not pos:
        return {"action": "wait_for_signal", "verdict": "idle"}
    worst = min(pos, key=lambda p: p.get("pnl", 0))
    best = max(pos, key=lambda p: p.get("pnl", 0))
    cfg = ctx.get("cfg") or {}
    if worst.get("pnl", 0) <= -cfg.get("sl_usd", 4) * 0.9:
        act = f"close_worst({worst.get('type')})"
    elif best.get("pnl", 0) >= cfg.get("tp_usd", 8) * 0.9:
        act = f"take_profit({best.get('type')})"
    elif acct.get("profit", 0) > 0:
        act = "trail_all"
    else:
        act = "hold"
    return {"action": act, "positions": len(pos), "verdict": act}

# -*- coding: utf-8 -*-
"""P12 — typesafe-mario: Jev plays a micro market game from RAM-like state.
No charts — only structured state; actions = run(buy)/jump(hold)/dodge(sell)."""
import random

META = {"id": "P12", "name": "arcade", "inspired_by": "typesafe-mario",
        "desc": "Structured-state arcade policy scored over a micro-sim."}


def run(ctx):
    rng = random.Random(int(ctx.get("cycles", 1)))
    fly = ctx.get("fly", {}).get("score", 0)
    price, lives, pts = 100.0, 3, 0
    for _ in range(120):
        shock = rng.gauss(0, 0.8) + (0.3 if fly > 0 else -0.3)
        action = "run" if fly > 0.1 else "dodge" if fly < -0.1 else "jump"
        if action == "run":
            pts += shock
        elif action == "dodge":
            pts -= shock * 0.5
        if shock < -2.2 and action == "run":
            lives -= 1
        price += shock
        if lives <= 0:
            break
    return {"game_points": round(pts, 1), "lives": lives,
            "policy": "fly-follow", "verdict":
            "win" if lives > 0 and pts > 0 else "game-over"}

