"""P15 — jev-trader: spread+flow driven market-making quotes (paper)."""
META = {"id": "P15", "name": "market_maker", "inspired_by": "jev-trader",
        "desc": "Judge buy/sell pressure from spread & flow, quote both sides."}


def run(ctx):
    tick = ctx.get("tick") or {}
    f = (ctx.get("feats") or {}).get("M1", {})
    spread = tick.get("spread") or 0.3
    flow = 1 if (f.get("volume") or "normal") in ("high", "very_high") else 0
    pressure = (ctx.get("fly") or {}).get("score", 0) * 0.5 + flow * 0.2
    if spread > 0.6:
        return {"quoting": False, "verdict": "spread too wide, stand down"}
    mid = (tick.get("bid", 0) + tick.get("ask", 0)) / 2
    skew = -pressure * spread
    return {"quoting": True,
            "bid_quote": round(mid - spread / 2 + skew, 2),
            "ask_quote": round(mid + spread / 2 + skew, 2),
            "pressure": round(pressure, 2),
            "verdict": "quote-both-sides" if abs(pressure) < 0.4
            else "skew-" + ("buy" if pressure > 0 else "sell")}

# -*- coding: utf-8 -*-
"""P16 — Prism: Jev never places orders; it judges toxic flow / pressure /
mean-reversion and gates the base strategy."""
META = {"id": "P16", "name": "prism", "inspired_by": "Prism",
        "desc": "Market-quality judge -> 0..1 gate for the base strategy."}


def run(ctx):
    f = (ctx.get("feats") or {}).get("M1", {})
    toxic = (f.get("volume") or "normal") in ("very_high",) and \
        (f.get("pattern") or ("", 0))[1] != 0
    pressure = abs(ctx.get("fly", {}).get("score", 0))
    revert = (f.get("bb_pb") or 0.5) < 0.08 or (f.get("bb_pb") or 0.5) > 0.92
    gate = 1.0
    labels = []
    if toxic:
        gate -= 0.6; labels.append("toxic_flow")
    if pressure > 0.7:
        gate -= 0.2; labels.append("extreme_pressure")
    if revert:
        gate += 0.0; labels.append("mean_reversion_zone")
    gate = round(max(0.0, min(1.0, gate)), 2)
    return {"gate": gate, "labels": labels,
            "verdict": "pass" if gate >= 0.6 else "block-entries"}

