"""P17 — neo4jev: knowledge-graph walk over regimes & strategies."""
META = {"id": "P17", "name": "neo4graph", "inspired_by": "neo4jev",
        "desc": "At each node pick the most worthwhile edge, follow it."}

EDGES = {
    "root": [("trending", 0.8), ("ranging", 0.5), ("volatile", 0.4)],
    "trending": [("ema_cross", 0.9), ("multi_tf_trend", 0.8),
                 ("macd_momentum", 0.6)],
    "ranging": [("bollinger_fade", 0.8), ("rsi_reversal", 0.7)],
    "volatile": [("fly_momentum", 0.7), ("candle_pattern", 0.5)],
}


def run(ctx):
    f = (ctx.get("feats") or {}).get("M1", {})
    regime = ("trending" if abs(f.get("mom") or 0) > 0.25
              else "volatile" if (f.get("atr") or 0) > 1.2 else "ranging")
    path = ["root", regime]
    node = regime
    for _ in range(2):
        edges = EDGES.get(node)
        if not edges:
            break
        node = max(edges, key=lambda e: e[1])[0]
        path.append(node)
    return {"path": path, "recommend": path[-1],
            "verdict": "->".join(path)}

# -*- coding: utf-8 -*-
"""P18 — jev-curate: tag journal trades for the next training round."""
META = {"id": "P18", "name": "curate", "inspired_by": "jev-curate",
        "desc": "Quality/relevance/risk pass over the trade journal."}


def tag(t):
    if t.get("pnl", 0) > 0 and t.get("reason") == "TP":
        return "high_quality"
    if t.get("pnl", 0) > 0:
        return "lucky_review"
    if t.get("reason") == "SL":
        return "expected_loss"
    return "risky_review"


def run(ctx):
    trades = ctx.get("journal_trades") or []
    counts = {}
    for t in trades:
        k = tag(t)
        counts[k] = counts.get(k, 0) + 1
    if not trades:
        j = ctx.get("journal") or {}
        counts = {"high_quality": int(j.get("winrate", 0) * j.get("trades", 0)
                                     / 100), "expected_loss":
                  j.get("trades", 0) - int(j.get("winrate", 0) *
                                           j.get("trades", 0) / 100)}
    keep = counts.get("high_quality", 0)
    total = sum(counts.values()) or 1
    return {"tags": counts, "keep_ratio": round(keep / total, 2),
            "verdict": f"keep {keep}/{total} for training"}

