/* Fly3D module 16/25 — live 3D candlestick wall the fly watches */
(function () {
  const N = 20;
  Fly3D.modules.push({
    name: 'candles3d',
    init(ctx) {
      const group = new THREE.Group();
      group.position.set(-6.5, 0, -5.5);
      group.rotation.y = 0.7;
      ctx.scene.add(group);
      const items = [];
      const bull = new THREE.MeshStandardMaterial({ color: 0x1d5c33,
        emissive: 0x3fb950, emissiveIntensity: 1.1, roughness: 0.3 });
      const bear = new THREE.MeshStandardMaterial({ color: 0x6d1d1d,
        emissive: 0xf85149, emissiveIntensity: 1.1, roughness: 0.3 });
      const wick = new THREE.LineBasicMaterial({ color: 0x8b949e });
      for (let i = 0; i < N; i++) {
        const body = new THREE.Mesh(new THREE.BoxGeometry(0.28, 1, 0.28),
          bull.clone());
        const wgeo = new THREE.BufferGeometry().setFromPoints(
          [new THREE.Vector3(), new THREE.Vector3()]);
        const wl = new THREE.Line(wgeo, wick);
        group.add(body, wl);
        items.push({ body, wl });
      }
      ctx.mods.candles3d = { group, items };
    },
    update(dt, s, ctx) {
      const c = s.candles;
      const C = ctx.mods.candles3d;
      if (!c || !c.closes || c.closes.length < 2) return;
      const n = Math.min(N, c.closes.length);
      const hi = Math.max(...c.highs.slice(-n));
      const lo = Math.min(...c.lows.slice(-n));
      const span = Math.max(hi - lo, 1e-9);
      const y = v => 0.3 + ((v - lo) / span) * 4.2;
      for (let i = 0; i < N; i++) {
        const it = C.items[i], j = c.closes.length - n + i;
        if (i >= n || j < 0) { it.body.visible = false; it.wl.visible = false; continue; }
        it.body.visible = true; it.wl.visible = true;
        const o = c.opens[j], cl = c.closes[j];
        const top = y(Math.max(o, cl)), bot = y(Math.min(o, cl));
        it.body.position.set(i * 0.42, (top + bot) / 2, 0);
        it.body.scale.y = Math.max(top - bot, 0.05);
        it.body.material.color.setHex(cl >= o ? 0x1d5c33 : 0x6d1d1d);
        it.body.material.emissive.setHex(cl >= o ? 0x3fb950 : 0xf85149);
        const p = it.wl.geometry.attributes.position;
        p.setXYZ(0, i * 0.42, y(c.highs[j]), 0);
        p.setXYZ(1, i * 0.42, y(c.lows[j]), 0);
        p.needsUpdate = true;
      }
    },
  });
})();

/* Fly3D module 17/25 — EMA21 ribbon floating over the candle wall */
(function () {
  Fly3D.modules.push({
    name: 'ema_ribbon',
    init(ctx) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(
        new Float32Array(20 * 3), 3));
      const line = new THREE.Line(geo, new THREE.LineBasicMaterial({
        color: 0x6495ff, linewidth: 2 }));
      ctx.mods.candles3d.group.add(line);
      ctx.mods.ema_ribbon = { line };
    },
    update(dt, s, ctx) {
      const c = s.candles;
      if (!c || !c.closes || c.closes.length < 3) return;
      const closes = c.closes;
      const k = 2 / 22; let ema = closes[0];
      const vals = closes.map(p => (ema = p * k + ema * (1 - k)));
      const n = Math.min(20, vals.length);
      const hi = Math.max(...c.highs.slice(-n));
      const lo = Math.min(...c.lows.slice(-n));
      const span = Math.max(hi - lo, 1e-9);
      const attr = ctx.mods.ema_ribbon.line.geometry.attributes.position;
      for (let i = 0; i < n; i++) {
        attr.setXYZ(i, i * 0.42,
          0.35 + ((vals[vals.length - n + i] - lo) / span) * 4.2, 0.2);
      }
      attr.needsUpdate = true;
    },
  });
})();

/* Fly3D module 18/25 — dopaminergic aura (score halo around the fly) */
(function () {
  function haloTexture() {
    const cv = document.createElement('canvas');
    cv.width = cv.height = 128;
    const g = cv.getContext('2d');
    const grad = g.createRadialGradient(64, 64, 4, 64, 64, 62);
    grad.addColorStop(0, 'rgba(255,255,255,0.9)');
    grad.addColorStop(0.4, 'rgba(255,255,255,0.25)');
    grad.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = grad; g.fillRect(0, 0, 128, 128);
    return new THREE.CanvasTexture(cv);
  }
  Fly3D.modules.push({
    name: 'score_aura',
    init(ctx) {
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({
        map: haloTexture(), transparent: true, depthWrite: false,
        blending: THREE.AdditiveBlending }));
      sp.position.set(0, 1.2, 0);
      ctx.scene.add(sp);
      ctx.mods.score_aura = { sp };
    },
    update(dt, s, ctx) {
      const t = Fly3D.theme();
      const a = ctx.mods.score_aura.sp;
      const mag = Math.min(Math.abs(s.score), 1);
      a.material.color.setHex(s.score > 0.05 ? t.bull :
        s.score < -0.05 ? t.bear : t.neon);
      a.material.opacity = 0.15 + mag * 0.5;
      const sc = 3 + mag * 2.5 + Math.sin(performance.now() / 400) * 0.15;
      a.scale.set(sc, sc, 1);
    },
  });
})();

/* Fly3D module 19/25 — eye/brain glow sprites (cheap bloom) */
(function () {
  Fly3D.modules.push({
    name: 'glow',
    init(ctx) {
      const mk = (color, size) => {
        const cv = document.createElement('canvas');
        cv.width = cv.height = 64;
        const g = cv.getContext('2d');
        const gr = g.createRadialGradient(32, 32, 2, 32, 32, 30);
        gr.addColorStop(0, 'rgba(255,255,255,1)');
        gr.addColorStop(1, 'rgba(255,255,255,0)');
        g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
        const sp = new THREE.Sprite(new THREE.SpriteMaterial({
          map: new THREE.CanvasTexture(cv), color, transparent: true,
          blending: THREE.AdditiveBlending, depthWrite: false }));
        sp.scale.set(size, size, 1);
        return sp;
      };
      const gL = mk(0xff4444, 0.7), gR = mk(0xff4444, 0.7),
            gB = mk(0xffd700, 1.6);
      gL.position.set(-0.24, 1.35, -0.82);
      gR.position.set(0.24, 1.35, -0.82);
      gB.position.set(0, 1.5, 0);
      ctx.scene.add(gL, gR, gB);
      ctx.mods.glow = { gL, gR, gB };
    },
    update(dt, s, ctx) {
      const G = ctx.mods.glow, t = Fly3D.theme();
      const ec = s.score > 0.05 ? t.bull : s.score < -0.05 ? t.bear : 0xaa6622;
      G.gL.material.color.setHex(ec); G.gR.material.color.setHex(ec);
      const pulse = 0.22 + Math.min(s.pam + s.ppl, 120) / 300;
      G.gL.material.opacity = G.gR.material.opacity = pulse;
      G.gB.material.opacity = 0.14 + Math.min(s.kc, 200) / 600;
    },
  });
})();

