/* Fly3D module 21/25 — viewport control deck (quality/rotate/theme) */
(function () {
  Fly3D.modules.push({
    name: 'controls_ui',
    init(ctx) {
      const bar = document.getElementById('fly3dControls');
      if (!bar) return;
      bar.innerHTML =
        '<button data-q="low">LOW</button>' +
        '<button data-q="mid">MID</button>' +
        '<button data-q="high" class="on">HIGH·166k</button>' +
        '<button data-r="1" class="on">ROTATE</button>' +
        '<button data-t="1">THEME</button>';
      bar.addEventListener('click', e => {
        const b = e.target;
        if (b.dataset.q) {
          Fly3D.set({ quality: b.dataset.q });
          const m = ctx.modsByName['neuron_cloud'];
          if (m && m.setQuality) m.setQuality(b.dataset.q);
          bar.querySelectorAll('[data-q]').forEach(x =>
            x.classList.toggle('on', x === b));
        }
        if (b.dataset.r) {
          Fly3D.set({ autoRotate: !Fly3D.state.autoRotate });
          b.classList.toggle('on', Fly3D.state.autoRotate);
        }
        if (b.dataset.t) {
          Fly3D.set({ theme: (Fly3D.state.theme + 1) % Fly3D.themes.length });
          const t = Fly3D.theme();
          ctx.scene.fog.color.setHex(t.bg);
          ctx.renderer.setClearColor(t.bg);
        }
      });
    },
    update() {},
  });
})();

/* Fly3D module 22/25 — FPS meter + automatic quality degradation */
(function () {
  Fly3D.modules.push({
    name: 'perf',
    init(ctx) {
      ctx.mods.perf = { frames: 0, t: performance.now(), slow: 0 };
    },
    update(dt, s, ctx) {
      const P = ctx.mods.perf;
      P.frames++;
      const now = performance.now();
      if (now - P.t >= 1000) {
        Fly3D.fps = Math.round(P.frames * 1000 / (now - P.t));
        P.frames = 0; P.t = now;
        if (Fly3D.fps < 26 && s.quality === 'high') {
          P.slow++;
          if (P.slow >= 3) {          // 3 slow seconds -> step down
            const next = s.quality === 'high' ? 'mid' : 'low';
            Fly3D.set({ quality: next });
            const m = ctx.modsByName['neuron_cloud'];
            if (m && m.setQuality) m.setQuality(next);
            P.slow = 0;
          }
        } else P.slow = 0;
      }
    },
  });
})();

/* Fly3D module 23/25 — rAF scheduler dispatching update() to all modules */
(function () {
  Fly3D.modules.push({
    name: 'animator',
    init(ctx) {
      ctx.start = () => {
        let last = performance.now();
        const loop = now => {
          const dt = Math.min((now - last) / 1000, 0.1);
          last = now;
          for (const m of Fly3D.modules) {
            if (m.update) { try { m.update(dt, Fly3D.state, ctx); } catch (e) {} }
          }
          requestAnimationFrame(loop);
        };
        requestAnimationFrame(loop);
      };
    },
    update() {},
  });
})();

/* Fly3D module 24/25 — socket.io bridge: server telemetry -> state */
(function () {
  Fly3D.modules.push({
    name: 'socket',
    init() {
      const sock = (typeof io !== 'undefined') ? io() : null;
      if (!sock) return;
      sock.on('update', d => {
        const f = d.fly_brain || {};
        Fly3D.set({
          pam: f.pam11 || 0, ppl: f.ppl101 || 0, kc: f.kc || 0,
          score: f.score || 0, spikes: f.spikes || 0,
          label: f.label || '--', conf: f.confidence || 0,
          status: f.status || 'live', price: d.price || 0,
          running: true, mode: d.mode || 'paper',
          candles: d.m1 || null,
        });
      });
      sock.on('disconnect', () => Fly3D.set({ running: false }));
      // restore last state so the room is alive immediately
      fetch('/api/state').then(r => r.json()).then(s => {
        const la = s.last_analysis;
        if (la && la.fly_brain) {
          const f = la.fly_brain;
          Fly3D.set({ pam: f.pam11 || 0, ppl: f.ppl101 || 0, kc: f.kc || 0,
            score: f.score || 0, spikes: f.spikes || 0,
            label: f.label || '--', candles: la.m1 || null });
        }
      }).catch(() => {});
    },
    update() {},
  });
})();

/* Fly3D module 25/25 — ordered bootstrap + graceful 2D fallback */
(function () {
  Fly3D.boot = function () {
    const ctx = { mods: {}, modsByName: {} };
    try {
      for (const m of Fly3D.modules) {
        if (m.init) m.init(ctx);
        ctx.modsByName[m.name] = m;
      }
      ctx.renderer.setClearColor(Fly3D.theme().bg);
      ctx.start();
      Fly3D.ok = true;
      console.info('[Fly3D] ' + Fly3D.modules.length + ' modules online');
    } catch (e) {
      console.warn('[Fly3D] falling back to 2D room:', e.message);
      Fly3D.ok = false;
      const vp = document.getElementById('fly3dViewport');
      const flat = document.getElementById('flyCanvas2d');
      if (vp && flat) { vp.classList.add('flat'); flat.style.display = 'block'; }
      if (window.__fly2d) window.__fly2d();   // dashboard 2D renderer
    }
  };
  Fly3D.modules.push({ name: 'bootstrap', init() {}, update() {} });
  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', Fly3D.boot);
  else Fly3D.boot();
})();
